input.command:
python3 - <<'EOF'
import json,os
a=json.load(open(os.environ['TMPDIR']+'/hoot.montagent.orig.json'));b=json.load(open('hoot.montagent.json'))
ea={e['id']:e for t in a['tracks'] for e in t['elements']}; eb={e['id']:e for t in b['tracks'] for e in t['elements']}
for id in ['owl-upper_arm_left','owl-forearm_left']:
  for prop in ['x','y','rotation']:
    ka={k['t']:k['v'] for k in ea[id][prop]}; kb={k['t']:k['v'] for k in eb[id][prop]}
    pre=all(ka.get(t)==kb.get(t) for t in set(ka)|set(kb) if t<=733)
    post=all(ka.get(t)==kb.get(t) for t in set(ka)|set(kb) if t>=3100)
    shift=[(t,ka[t],kb.get(t+400)) for t in ka if 733<t<=2250 and ka[t]!=kb.get(t+400)]
    print(id,prop,'pre',pre,'post',post,'shift-mismatch',shift[:5])
EOF

